def transform(grid):
    # Preserve colored input markers; draw nested alternating square outlines centered on the 3.
    out=[row[:] for row in grid]
    n=len(grid)
    cr=next(r for r in range(n) for c in range(n) if grid[r][c]==3)
    cc=next(c for r in range(n) for c in range(n) if grid[r][c]==3)
    for d in range(1, max(n-cr,cr+1,n-cc,cc+1)):
        top,bottom,left,right=cr-d,cr+d,cc-d,cc+d
        if top<0 or bottom>=n or left<0 or right>=n: continue
        # squares are drawn with gaps, forming the observed nested pattern
        for c in range(left,right+1):
            if (d%2)==1:
                if c not in (left+1,right-1): out[top][c]=3
            else:
                out[bottom][c]=3
        for r in range(top,bottom+1):
            if (d%2)==1:
                if r not in (top+1,bottom-1): out[r][left]=3; out[r][right]=3
            else:
                out[r][left]=3; out[r][right]=3
    return out
