def transform(grid):
    out=[r[:] for r in grid]
    n=len(grid)
    cr,cc=next((r,c) for r in range(n) for c in range(n) if grid[r][c]==3)
    # Concentric open-square paths, successively inset; one side is open to make a spiral.
    for k in range(0, min(cr,cc,n-1-cr,n-1-cc)+1):
        t,l=cr-k,cc-k
        b,r=cr+k,cc+k
        if k==0: continue
        # observed pattern: nested square outlines, each with a gap on alternating sides
        for c in range(l,r+1):
            if k%2==1:
                if c!=l: out[t][c]=3
                if c!=r: out[b][c]=3
            else:
                out[t][c]=3; out[b][c]=3
        for y in range(t,b+1):
            if k%2==1:
                out[y][l]=3
                if y!=b: out[y][r]=3
            else:
                out[y][l]=3; out[y][r]=3
    return out
